import { test, expect } from '@playwright/test';

test.describe('Customer Login to Sauce Demo Store', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should successfully log in a registered customer and reach the product catalogue', async ({ page }) => {
    // Locate and fill username field using getByRole
    const usernameField = page.getByLabel('Username');
    await expect(usernameField).toBeVisible();
    await usernameField.fill('standard_user');

    // Locate and fill password field using getByRole
    const passwordField = page.getByLabel('Password');
    await expect(passwordField).toBeVisible();
    await passwordField.fill('secret_sauce');

    // Locate and click login button using getByRole
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();
    await loginButton.click();

    // Verify successful login by checking URL
    await expect(page).toHaveURL(/.*inventory\.html/);

    // Verify page title element contains 'Products'
    const pageTitle = page.getByText('Products');
    await expect(pageTitle).toBeVisible();
  });

  test('should display error message when login credentials are invalid', async ({ page }) => {
    // Locate and fill username field using getByRole
    const usernameField = page.getByLabel('Username');
    await expect(usernameField).toBeVisible();
    await usernameField.fill('invalid_user');

    // Locate and fill password field using getByRole
    const passwordField = page.getByLabel('Password');
    await expect(passwordField).toBeVisible();
    await passwordField.fill('wrong_password');

    // Locate and click login button using getByRole
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();
    await loginButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText('Epic sadface: Username and password do not match');
    await expect(errorMessage).toBeVisible();

    // Verify user is still on login page
    await expect(page).toHaveURL(/.*login\.html/);
  });
});
